            rs=[p[0]-cells[0][0] for p in cells]; cls=[p[1]-cells[0][1] for p in cells]
            comps.append((v,tuple(zip(rs,cls))))
byshape=defaultdict(list)
for c in comps: byshape[c[1]].append(c[0])
for sh,lst in byshape.items():
